#!/usr/bin/env python3
"""Current 0.8.5 candidate guidance; keep historical candidates and stable APK."""
from pathlib import Path
import re
import struct
ROOT=Path(__file__).resolve().parents[1]; D=ROOT/'docs'
shell=(D/'preview-084.html').read_text()
head=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->','',shell[:shell.index('<main')],flags=re.S)
head=head.replace('0.8.4','0.8.5').replace('preview-084.html','preview-085.html')
foot=shell[shell.index('<footer'):]
body='''<main id="main" tabindex="-1"><section class="section wrap preview-intro"><p class="eyebrow">Android candidate · 0.8.5</p><h1>MeBot 0.8.5</h1><p class="lead">Add interests in your own words, simplify your personal context and find topics more easily.</p><div class="preview-status"><strong>Preview, not a published APK</strong><p>The media-inclusive candidate passed 878 local automated tests and release assembly. Updated candidate CI remains pending. Release signing and physical-phone acceptance are still pending. The official download remains 0.8.2; do not uninstall your existing app to try a file with an incompatible signature.</p><div class="actions"><a class="button" href="download.html">Get official 0.8.2</a><a class="button secondary" href="#changes">Explore 0.8.5 changes</a></div></div></section>
<section class="section wrap hairline" id="changes"><h2>Make MeBot yours with less setup</h2><div class="preview-guide"><article><span class="preview-number">01</span><div><h3>Your interests, in your words</h3><p>Onboarding lets you add custom interests as well as select topics. A live count helps you stay within <strong>150 words and 1,000 characters</strong>. Words are separated by whitespace, including Unicode whitespace. Both limits apply; the app does not silently shorten your text.</p><p>Your custom interests are saved with explicit topic scope. They are not automatically shared with every module.</p></div></article><article><span class="preview-number">02</span><div><h3>One place to introduce yourself</h3><p><strong>About you</strong> is your shared profile for all modules. Its global use starts only when you explicitly save it. Use the main text area for your work, interests and what you want to follow. Optional Help offers an English or Kiswahili example about a person in Tanzania who owns several small businesses; it is not inserted or saved automatically.</p><p>Choose to insert an example yourself. If you already wrote something, confirm before replacing it. Separate notes appear visibly below your profile. Add, edit or remove a note and choose which modules can use it. Earlier records and onboarding interests remain separate scoped notes, not automatically promoted to your global profile. Imported context does not gain global access until you explicitly save an About-you profile.</p><p>Location, time zone and import/export options are grouped under <strong>Location, time zone &amp; transfer</strong>, while Save details stays prominent. Check your changes before saving.</p></div></article><article><span class="preview-number">03</span><div><h3>Find topics and saved reading more easily</h3><p>Modules uses a compact search field and horizontal filter rows, leaving more room for topics. Saved and Following have a clearer hierarchy: bookmarks keep reading, while stars follow stories. Manage follow-up timing in <strong>Saved → Following</strong>.</p><p>The price-comparison tool has been removed from 0.8.5. An older saved route to that tool returns safely to Modules. Other everyday tools remain available.</p></div></article></div></section>
<section class="section wrap hairline" lang="sw"><p class="eyebrow">Kwa kifupi</p><h2>Eleza unachopenda kwa maneno yako</h2><p>Ongeza unachopenda wakati wa kuanza, hadi maneno 150 na herufi 1,000. Hesabu inaonekana unapochapa; maandishi yako hayafupishwi kimya kimya. Kwenye Kuhusu wewe, tumia sehemu moja kueleza kazi, mambo unayopenda na unayotaka kufuatilia.</p><p>Mfano wa Usaidizi ni wa hiari. Unaamua kuuingiza, na utaombwa kuthibitisha kabla ya kubadilisha maandishi yaliyopo. Maelezo ya Kuhusu wewe hutumiwa na mada zote baada ya kuyahifadhi mwenyewe. Vidokezo vingine vinaonekana chini yake: unaweza kuongeza, kuhariri au kuondoa kidokezo na kuchagua mada zinazoweza kukitumia. Maelezo ya awali hayabadilishwi kimya kimya kuwa wasifu wa jumla. Zana ya kulinganisha bei imeondolewa katika 0.8.5.</p><p>Upakuaji rasmi uliopo bado ni 0.8.2.</p></section>
<section class="section wrap hairline"><h2>Before a signed release</h2><p>The final local gate passed 189 core, 509 Android and 180 service tests, with zero failures, errors or skips. Release assembly and ZIP alignment passed. Lint reported zero errors, 225 debug warnings, 226 release warnings and one hint per variant. The APK is unsigned; device and signing checks remain separate.</p><p>If the same production package uses a new signing certificate, it cannot update the old 0.8.2 installation in place. Export portable preferences before any owner-controlled reinstall; this does not promise that every kind of app data can be restored. MeBot will not automatically uninstall your existing app.</p><h2>Documents and media</h2><p>The PDF viewer offers fullscreen page navigation, fit and zoom controls. Its host UI capture uses locally pre-rendered synthetic pages, not proof of physical-phone PDF decoding. YouTube keeps its provider fullscreen and quality controls where offered. Direct MP4, WebM and HLS use the Android player and supported device codecs. Unsupported resources or playback errors offer the original link. This is not a promise of DASH, DRM or universal stream compatibility.</p><h2>Connected providers</h2><p>If you use the self-hosted MeBot service, update it together with the app so global profile and scoped-note handling match. Direct provider connections do not require the service. This does not establish live provider access.</p><h2>What stays the same</h2><p>The icon-only star beside the bookmark, source-dependent fullscreen media, optional notifications and normal request allowances remain. Provider-supported controls do not guarantee that every video can play. Device speech input and installed-voice read-aloud are not full-duplex realtime voice.</p><p>Native captures use controlled example content. They show the interface, not live provider authorization, physical-phone installation, real streaming, notification delivery or overnight alarms.</p><div class="actions"><a class="button secondary" href="RELEASE-0.8.5.md">0.8.5 candidate notes</a><a class="text-link" href="preview-084.html">0.8.4 history →</a><a class="text-link" href="preview-083.html">0.8.3 history →</a><a class="text-link" href="guide.html">Official 0.8.2 guide →</a></div></section></main>'''
captures=[('about','Your shared profile','Native About-you profile after explicitly inserting the optional Tanzania business-owner example; test fixture, not a saved default.'),('notes','Separate scoped notes','Native context notes below the profile, with edit/remove and chosen-topic controls; sample data.'),('interests','Your own interests','Native onboarding with custom-interest input and live limits; sample text.'),('modules','Find a topic','Native Modules screen with compact search and horizontal filters.'),('saved','Saved reading','Native library hierarchy with controlled sample content.'),('following','Followed stories','Native Following view with manual cadence management; controlled source fixtures.'),('feed','A star beside the bookmark','Current native feed render with icon-only star; dated public-source test fixture.'),('pdf','Fullscreen PDF','Native Android page and zoom controls with locally pre-rendered synthetic PDF pages; not proof of phone PDF decoding.'),('fullscreen','Fullscreen image','Native fullscreen image viewer; labelled local image fixture, not live video playback.')]
figures=[]
for name,title,caption in captures:
    p=D/'screenshots/v085'/f'{name}.png'
    if not p.exists(): continue
    w,h=struct.unpack('>II',p.read_bytes()[16:24])
    figures.append(f'<figure class="shot"><a href="screenshots/v085/{name}.png" data-lightbox data-title="{title}" aria-label="Enlarge: {title}"><img src="screenshots/v085/{name}.png" width="{w}" height="{h}" loading="lazy" alt="{caption}"></a><figcaption><span class="shot-version">0.8.5 candidate · native render</span><strong>{title}</strong><span>{caption}</span></figcaption></figure>')
if figures:
    gallery='<section class="section wrap hairline"><h2>Native candidate preview</h2><div class="screen-grid">'+''.join(figures)+'</div><p class="micro"><a href="screenshots/v085/README.md">Capture provenance</a></p></section>'
    body=body.replace('<section class="section wrap hairline" id="changes">',gallery+'<section class="section wrap hairline" id="changes">')
(D/'preview-085.html').write_text(head+body+foot)
for p in [*D.glob('*.html'),*(D/'guides').glob('*.html')]:
    if p.name=='preview-085.html': continue
    t=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->','',p.read_text(),flags=re.S)
    rel='../' if p.parent.name=='guides' else ''
    banner=f'<!-- preview-085:start --><aside class="preview-banner"><strong>0.8.5 preview</strong> · Custom interests, simpler personal context and clearer navigation. <a href="{rel}preview-085.html">See changes and release status →</a></aside><!-- preview-085:end -->'
    p.write_text(t.replace('</header>','</header>'+banner,1))
for p,link in [(ROOT/'README.md','docs/RELEASE-0.8.5.md'),(ROOT/'START-HERE.md','docs/RELEASE-0.8.5.md'),(D/'USER-GUIDE.md','RELEASE-0.8.5.md')]:
    t=re.sub(r'<!-- preview-08[345]:start -->.*?<!-- preview-08[345]:end -->\n*','',p.read_text(),flags=re.S)
    p.write_text(f'<!-- preview-085:start -->\n> **0.8.5 candidate:** Custom interests, a simpler About you screen and clearer navigation; 878 local automated tests passed. [Current candidate guide]({link}). The official download remains **0.8.2**. Earlier candidate release notes are preserved as history.\n<!-- preview-085:end -->\n\n'+t)
print('Updated 0.8.5 current guidance; preserved prior candidate history and official 0.8.2 download.')
